{"code": "export async function main(input: any) {
  const counts: Record<string, number> = {};
  let cursor: string | undefined = undefined;
  let pages = 0;
  const perPage: number[] = [];
  let earliest = "";
  let latest = "";
  let beforeSince = 0;
  const since = "2026-09-01T00:00:00Z";
  const sinceMs = Date.parse(since);
  while (true) {
    const res = await sdk.github.listCommits({ since, cursor });
    pages++;
    perPage.push(res.commits.length);
    for (const c of res.commits) {
      const ms = Date.parse(c.committedAt);
      if (ms < sinceMs) { beforeSince++; continue; }
      counts[c.authorEmail] = (counts[c.authorEmail] ?? 0) + 1;
      if (!earliest || ms < Date.parse(earliest)) earliest = c.committedAt;
      if (!latest || ms > Date.parse(latest)) latest = c.committedAt;
    }
    if (!res.nextCursor) break;
    cursor = res.nextCursor;
  }
  return { counts, pages, perPage, beforeSince, earliest, latest };
}", "input": {}}
